#!/usr/bin/env bash
# Colar inteiro na VPS (root). Sem GitHub. Corrige Aplicar modo BetBra.
set -euo pipefail
export BOTSHIELD_WEB="${BOTSHIELD_WEB:-/var/www/arbishield-botshield}"
export ARBISHIELD_SHIM_DIR="${ARBISHIELD_SHIM_DIR:-/opt/arbishield}"
export ARBISHIELD_SCRIPTS="${ARBISHIELD_SCRIPTS:-$ARBISHIELD_SHIM_DIR/scripts}"
python3 - <<'PY'
import base64, zlib, pathlib, os
web = os.environ["BOTSHIELD_WEB"]
shim = os.environ["ARBISHIELD_SHIM_DIR"]
scr = os.environ["ARBISHIELD_SCRIPTS"]
html = zlib.decompress(base64.b64decode(""))
svc = zlib.decompress(base64.b64decode(""))
pathlib.Path(web).mkdir(parents=True, exist_ok=True)
(pathlib.Path(web) / "integracoes.html").write_bytes(html)
for d in [scr + '/lib', shim + '/lib', shim + '/scripts/lib']:
    pathlib.Path(d).mkdir(parents=True, exist_ok=True)
    (pathlib.Path(d) / "exchange-orders-service.mjs").write_bytes(svc)
assert b"useSaved" in html and b"useSaved" in svc
print("OK wrote", web + "/integracoes.html")
print("OK wrote exchange-orders-service.mjs")
PY
systemctl restart arbishield-serverfn-shim.service 2>/dev/null || true
systemctl is-active arbishield-serverfn-shim.service || true
echo "OK. Hard refresh: https://botshield.arbishield.app/integracoes.html"
